/// Gradient palettes for the corporate mark, generated from tokens.json
/// `themes`. `EmblemRenderer.paint(..., theme: 'neon')` swaps a spec's gradient
/// at runtime, so a festival/mood reskin needs no new logo assets.
class EmblemTheme {
  final String key;
  final String label;

  /// CSS-style gradient angle: 0 = up, 90 = right, 135 = top-left -> bottom-right.
  final double angleDeg;

  /// 0xAARRGGBB stops, evenly spaced.
  final List<int> stops;

  const EmblemTheme(this.key, this.label, this.angleDeg, this.stops);
}

