/// Seasonal liveries from brand/occasions.json. One treatment dresses the whole
/// family at once (rim tint + anatomy accent + a rim ornament) — never a single
/// mark. `EmblemOccasion.forDate(DateTime.now())` picks today's, if any.
class EmblemOccasion {
  final String key;

  /// Full label, e.g. `Diwali`.
  final String label;

  /// One-line note, e.g. `Festival of Lights`.
  final String subtitle;

  /// `MM-DD` for annual dates, `YYYY-MM-DD` for lunar festivals.
  final List<String> dates;

  /// Rim ring colour, 0xAARRGGBB.
  final int rim;

  /// Anatomy glow colour, 0xAARRGGBB.
  final int accent;

  /// Secondary anatomy colour (`sonarBlue`), 0xAARRGGBB. Marks that use two
  /// channels keep their depth in livery instead of flattening to one hue.
  final int accentDim;

  const EmblemOccasion(this.key, this.label, this.subtitle, this.dates,
      this.rim, this.accent, this.accentDim);
}

